'use strict';
// Apoio de leitura, não transcrição fonética nem substituto de pinyin/escuta.
const BR_SYLLABLES = Object.fromEntries(`ba=bá bai=bai bang=bang bao=bau bei=bêi ben=bân bi=bi bian=biên biao=biau bing=bing bo=buô bu=bu cai=ts'hai ce=ts'hâ cha=tchhá chang=tchhang cheng=tchhâng chi=tchhrr chong=tchhong chu=tchhu chuan=tchhuan ci=ts'hrr cun=ts'huên cuo=ts'huô da=dá dai=dai dan=dan dao=dau de=dâ dei=dêi deng=dâng di=di dianr=diênr ding=ding dong=dong dou=dôu du=du dui=duêi duo=duô e=â er=âr fa=fá fan=fan fang=fang fei=fêi fen=fân fou=fôu fu=fu gai=gai gan=gan gao=gau ge=gâ geng=gâng gong=gong gu=gu guan=guan guo=guô hai=rrái hao=rráu he=rrâ hen=rrân hua=rruá huan=rruan hui=rruêi huo=rruô ji=dji jia=djia jian=djiên jiang=djiang jiao=djiau jie=djiê jin=djin jing=djing jiu=djiôu ju=djü jue=djüê ka=khá kan=khan kao=khau ke=khâ lai=lai lang=lang le=lâ li=li lian=liên liang=liang lu=lu lun=luên lv=lü ma=má man=man mang=mang me=mâ mei=mêi men=mân mian=miên ming=ming mu=mu na=ná nar=nár neng=nâng ni=ni pi=phi pian=phiên piao=phiau pin=phin ping=phing qi=tchi qian=tchiên qing=tching qu=tchü que=tchüê ran=rran ren=rrân reng=rrâng ri=rrr ru=rru shang=shang shao=shau she=shâ shen=shân sheng=shâng shi=shrr shou=shôu shu=shu shua=shuá shuo=shuô song=song su=su sui=suêi tai=thai tan=than ti=thi tian=thiên tiao=thiau tie=thiê tong=thong wan=uan wei=uêi wen=uên wo=uô wu=u xi=shi xia=shia xian=shiên xiang=shiang xiao=shiau xie=shiê xin=shin xing=shing xiu=shiôu xu=shü xuan=shüên xue=shüê yan=iên yang=iang yao=iau yi=i yin=in ying=ing you=iôu yu=ü yue=üê zai=dzai zao=dzau zhan=djan zhang=djang zhe=djâ zheng=djâng zhi=djrr zhong=djong zhou=djôu zhu=dju zhun=djuên zi=dzrr zou=dzôu zui=dzuêi zuo=dzuô`.split(' ').map(s=>s.split('=')));
function syllables(raw){return raw.trim().split(/\s+/).map(s=>{const m=s.match(/^([a-zü]+)([1-5])$/i);if(!m)throw Error('Pinyin inválido: '+s);return {base:m[1].toLowerCase(),tone:Number(m[2])}})}
function toneMark(base,tone){base=base.replace(/v/g,'ü');if(tone===5)return base;let index=base.indexOf('a');if(index<0)index=base.indexOf('e');if(index<0&&base.includes('ou'))index=base.indexOf('o');if(index<0){for(let i=base.length-1;i>=0;i--)if('aeiouü'.includes(base[i])){index=i;break}}if(index<0)return base;const vowels={a:'āáǎà',e:'ēéěè',i:'īíǐì',o:'ōóǒò',u:'ūúǔù',ü:'ǖǘǚǜ'};return base.slice(0,index)+vowels[base[index]][tone-1]+base.slice(index+1)}
function pinyin(raw){return syllables(raw).map(s=>toneMark(s.base,s.tone)).join(' ')}
function chinesePronunciation(raw){const s=syllables(raw);const arrows={1:'¹',2:'²',3:'³',4:'⁴',5:'·'};return s.map(t=>{if(!BR_SYLLABLES[t.base])throw Error('Ponte BR ausente: '+t.base);return BR_SYLLABLES[t.base]+arrows[t.tone]}).join(' ')}
function toneNotes(raw){const s=syllables(raw),notes=[];let thirdPairs=0;for(let i=0;i<s.length-1;i++)if(s[i].tone===3&&s[i+1].tone===3)thirdPairs++;if(thirdPairs)notes.push('Há terceiros tons consecutivos: em um grupo de dois, o primeiro costuma soar como 2º tom. Sequências maiores dependem do agrupamento; os números abaixo mantêm os tons de referência.');if(s.some(t=>t.base==='yi'&&[2,4].includes(t.tone)))notes.push('一 já aparece com o tom ajustado nesta leitura: yí antes de 4º tom; yì antes de 1º, 2º ou 3º.');if(s.some(t=>t.base==='bu'&&t.tone===2))notes.push('不 aparece como bú antes de 4º tom.');if(s.some(t=>t.tone===5))notes.push('O ponto · indica tom neutro: curto e leve, sem contorno fixo independente.');if(!notes.length)notes.push('Siga os tons do pinyin e mantenha a frase em grupos de sentido. O 3º tom costuma ficar baixo antes de tons diferentes do 3º.');return notes.join(' ')}
function normalizeSearch(s){return String(s).toLowerCase().normalize('NFD').replace(/[\u0300-\u036f]/g,'').replace(/ü/g,'u')}
